  @protected
  void sse_encode_card_key(CardKey self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case CardKey_Note(id: final id):
        sse_encode_i_32(0, serializer);
        sse_encode_String(id, serializer);
      case CardKey_Task(
        noteId: final noteId,
        line: final line,
        text: final text,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(noteId, serializer);
        sse_encode_u_32(line, serializer);
        sse_encode_String(text, serializer);
    }
  }

  @protected
  void sse_encode_card_moved(CardMoved self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case CardMoved_Changed(message: final message, undo: final undo):
        sse_encode_i_32(0, serializer);
        sse_encode_opt_String(message, serializer);
        sse_encode_opt_CastedPrimitive_u_64(undo, serializer);
      case CardMoved_Unchanged():
        sse_encode_i_32(1, serializer);
      case CardMoved_Missing():
        sse_encode_i_32(2, serializer);
    }
  }

